FROM t_message
WHERE is_deleted = 0
  AND recipient_user_id = #{userId}

    AND message_type = #{query.messageType}


    AND read_status = #{query.readStatus}


    AND priority = #{query.priority}

mapper.select:
SELECT 

ORDER BY read_status ASC, priority DESC, create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM t_message
WHERE is_deleted = 0 AND recipient_user_id = #{userId}
  AND message_type = #{messageType}
